import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const l="/docs/images/sheets/sort-and-filter-values.png",f=JSON.parse('{"title":"Sort and filter","description":"Turn a table into a filtered range, then sort it by a column or show only the rows that match values or a condition.","frontmatter":{"title":"Sort and filter","description":"Turn a table into a filtered range, then sort it by a column or show only the rows that match values or a condition.","type":"how-to"},"headers":[],"relativePath":"sheets/sort-and-filter.md","filePath":"sheets/sort-and-filter.md"}'),n={name:"sheets/sort-and-filter.md"};function i(s,e,h,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sort-and-filter" tabindex="-1">Sort and filter <a class="header-anchor" href="#sort-and-filter" aria-label="Permalink to &quot;Sort and filter&quot;">​</a></h1><p>Turn a table into a filtered range, then sort it by a column or show only the rows that match values or a condition.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access to create, change, or clear a filter.</li><li>The filter is saved with the tab, so everyone sees the same rows hidden.</li><li>Each tab has one filter at a time.</li></ul></div><h2 id="create-a-filter" tabindex="-1">Create a filter <a class="header-anchor" href="#create-a-filter" aria-label="Permalink to &quot;Create a filter&quot;">​</a></h2><ol><li>Select the table, including its header row. Or click any one cell in the table.</li><li>Click <strong>Create filter from selection</strong> (the funnel icon) in the toolbar.</li></ol><p>A filter button appears in each header cell. The top row of the range is the header row and is never sorted or hidden.</p><p>When you start from a single cell, the filter grows to cover the whole block of data around it. When you select only the header row, it extends down through the rows that have data.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap ⋮ (<strong>More formatting options</strong>) and select <strong>Create filter</strong>.</p><h2 id="sort-by-a-column" tabindex="-1">Sort by a column <a class="header-anchor" href="#sort-by-a-column" aria-label="Permalink to &quot;Sort by a column&quot;">​</a></h2><ol><li>Click the filter button in the header of the column to sort by. A panel named for the column, such as <strong>Filter B</strong>, opens.</li><li>Under <strong>Sort</strong>, click <strong>Sort A to Z</strong> or <strong>Sort Z to A</strong>.</li></ol><p>Rows in the filter range are reordered by that column. Numbers sort by value, text sorts alphabetically ignoring case, and empty cells go last. Formulas recalculate after the sort.</p><h2 id="filter-by-values" tabindex="-1">Filter by values <a class="header-anchor" href="#filter-by-values" aria-label="Permalink to &quot;Filter by values&quot;">​</a></h2><ol><li>Click the filter button in a column header.</li><li>Click <strong>Filter by values</strong>. The panel lists each distinct value in the column, with <strong>(Blanks)</strong> for empty cells.</li><li>Clear the check box next to each value to hide. To find a value, type in <strong>Search values</strong>. To check or clear all, use <strong>Select all</strong>.</li><li>Click <strong>Apply</strong>.</li></ol><p>Rows whose value is unchecked are hidden. The panel shows how many values are selected, such as <strong>Selected 3 / 5</strong>.</p><p><img src="'+l+'" alt="Column filter panel with Sort A to Z, Filter by values, a value list, and the Apply button"></p><h2 id="filter-by-condition" tabindex="-1">Filter by condition <a class="header-anchor" href="#filter-by-condition" aria-label="Permalink to &quot;Filter by condition&quot;">​</a></h2><ol><li>Click the filter button in a column header.</li><li>Click <strong>Filter by condition</strong>.</li><li>Select a condition: <strong>Contains</strong>, <strong>Does not contain</strong>, <strong>Equals</strong>, <strong>Does not equal</strong>, <strong>Is empty</strong>, or <strong>Is not empty</strong>.</li><li>Type a value in <strong>Enter value</strong>, unless the condition is <strong>Is empty</strong> or <strong>Is not empty</strong>.</li><li>Click <strong>Apply</strong>.</li></ol><p>Conditions ignore case. When you filter several columns, a row stays visible only if it matches every column&#39;s filter.</p><h2 id="clear-a-filter" tabindex="-1">Clear a filter <a class="header-anchor" href="#clear-a-filter" aria-label="Permalink to &quot;Clear a filter&quot;">​</a></h2><ul><li><strong>One column:</strong> click its filter button and click <strong>Clear</strong>. <strong>Clear</strong> is unavailable until that column has a filter.</li><li><strong>The whole filter:</strong> click <strong>Clear filter</strong> (the funnel icon) in the toolbar. On a phone, tap ⋮ and select <strong>Clear filter</strong>.</li></ul><p>Clearing shows every row again and removes the filter buttons.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Sorting needs a filter. There is no sort command outside the filter panel.</li><li>A sort does nothing when any merged cell sits in the rows being sorted, even in a column outside the filter. Unmerge it first.</li><li>Sorting moves cells only within the filter range&#39;s columns. Data in other columns of the same rows stays where it is, so include every related column in the filter.</li><li>To create a filter, select cells, not whole rows or columns. The range needs at least one row below the header.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/rows-columns-tabs.html">Rows, columns, and tabs</a> to hide rows by hand or freeze the header row.</li><li><a href="/docs/sheets/conditional-formatting.html">Conditional formatting</a> to highlight matches instead of hiding the rest.</li><li><a href="/docs/sheets/formulas.html">Formulas</a> to return a sorted copy of a range with <code>SORT</code>.</li></ul>',26)])])}const m=t(n,[["render",i]]);export{f as __pageData,m as default};
